import{_ as o,o as n,c as i,j as a,a as r,G as s,aa as d,B as l}from"./chunks/framework.VLjJFeoF.js";const v=JSON.parse('{"title":"开发运维一体化","description":"","frontmatter":{},"headers":[],"relativePath":"docs/devops/index.md","filePath":"docs/devops/index.md","lastUpdated":1769531044000}'),u={name:"docs/devops/index.md"};function c(p,e,h,m,C,_){const t=l("ArticleMetadata");return n(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1769531044000"},[e[0]||(e[0]=a("h1",{id:"开发运维一体化",tabindex:"-1"},[r("开发运维一体化 "),a("a",{class:"header-anchor",href:"#开发运维一体化","aria-label":'Permalink to "开发运维一体化"'},"​")],-1)),s(t,{article:{}}),e[1]||(e[1]=d('<h2 id="devops" tabindex="-1">DevOps <a class="header-anchor" href="#devops" aria-label="Permalink to &quot;DevOps&quot;">​</a></h2><p>DevOps 是一种软件开发和运维（Operations）的文化、理念和实践方法，旨在通过改善开发团队和运维团队之间的协作和沟通，实现软件开发、测试、部署和运维过程的自动化、持续集成、持续交付和持续部署，从而加速软件交付并提高产品质量和稳定性。</p><p>这里的 DevOps 包含以下方面:</p><ul><li>持续集成（Continuous Integration，CI）</li><li>持续交付（Continuous Delivery，CD）</li><li>持续部署（Continuous Deployment，CD）</li></ul><h2 id="持续集成-continuous-integration-ci" tabindex="-1">持续集成（Continuous Integration，CI） <a class="header-anchor" href="#持续集成-continuous-integration-ci" aria-label="Permalink to &quot;持续集成（Continuous Integration，CI）&quot;">​</a></h2><p>将开发人员的代码频繁地集成到共享存储库中，并自动进行构建、测试和代码静态分析，以确保新代码不会破坏现有功能，并尽早发现和修复问题。</p><h2 id="持续交付-continuous-delivery-cd" tabindex="-1">持续交付（Continuous Delivery，CD） <a class="header-anchor" href="#持续交付-continuous-delivery-cd" aria-label="Permalink to &quot;持续交付（Continuous Delivery，CD）&quot;">​</a></h2><p>自动化构建、测试和部署过程，以便在任何时候都能够快速、可靠地将应用程序交付给生产环境。</p><h2 id="持续部署-continuous-deployment-cd" tabindex="-1">持续部署（Continuous Deployment，CD） <a class="header-anchor" href="#持续部署-continuous-deployment-cd" aria-label="Permalink to &quot;持续部署（Continuous Deployment，CD）&quot;">​</a></h2><p>在通过持续交付自动化流水线之后，进一步自动化将应用程序部署到生产环境，以实现快速且可靠地将变更部署到生产环境。</p>',10))])}const f=o(u,[["render",c]]);export{v as __pageData,f as default};
